(()=>{const n=()=>{document.body.innerHTML='\n    <div style="text-align: center; margin-top: 20%;">\n      <h1>You are offline</h1>\n      <p>Try turning on Wi-Fi or mobile data and we\'ll get you back.</p>\n      <div>\n        <svg xmlns="http://www.w3.org/2000/svg" width="84" height="84" viewBox="0 0 24 24" fill="none" stroke="#af4848" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="feather feather-wifi">\n          <path d="M5 12.55a11 11 0 0 1 14.08 0"></path>\n          <path d="M1.42 9a16 16 0 0 1 21.16 0"></path>\n          <path d="M8.53 16.11a6 6 0 0 1 6.95 0"></path>\n          <line x1="12" y1="20" x2="12.01" y2="20"></line>\n        </svg>\n      </div>\n    </div>\n  '};window.addEventListener("load",()=>{navigator.onLine||n()}),window.addEventListener("online",()=>{location.reload()}),window.addEventListener("offline",()=>{n()}),"localhost"===location.hostname||"127.0.0.1"===location.hostname||location.origin})();